from __future__ import print_function

import time

import six
from ute_ue.data_transfers.lte_data_transfer import LteDataTransfer
from ute_ue.exceptions import DataTransferIllegalArguments

from ta_ue_plugin_android.ue.common.action_flow import ActionGate
from ta_ue_plugin_android.uepc.datatransfer.data_transfer_utils import IperfServerReportRow, get_ip_version
from ta_ue_plugin_android.uepc.ue_manager_exceptions import DataTransferException, DtConfigOptionMissingException, \
    AppServerNotAvailableException, AppServerNotSelectedException

UNIT_OF_DT_DEFINITION_THROUGHPUT = 'k'


class AndroidDataTransfer(LteDataTransfer):  # pylint: disable=unnecessary-pass
    """Object responsible for managing Android data transfer."""

    # pylint: disable=protected-access, too-many-instance-attributes
    def __init__(self, name, dt_definition, configuration, ue_instance, logger_name='ute_ue'):
        """

        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: tool dependant configuration provided by UE instance needed for data transfer operations
        :param android_ue:
        """
        super(AndroidDataTransfer, self).__init__(name, dt_definition, configuration, logger_name)
        # inside super.__init__ were execued:
        # self.name = name
        # self._dt_definition = dt_definition
        # self._configuration = configuration
        # and logger created
        self.is_dt_running = False
        self.success_started = False
        self.stopping_gate = ActionGate()
        self.ue_instance = ue_instance
        self.logger.debug('"{}" instance of AndroidDataTransfer created: '.format(self.name))
        self.datagram_loss_readed = False
        self.avg_throughput = None
        self.datagram_loss = None
        self.iperf_cmds = {}
        self.client_lines_report, self.server_lines_report = [], []
        self.reports_received = False

    def start(self):
        """
        Starts data transfer with parameters defined in dt_definition passed during initialization.
        :return: None
        """
        if self._dt_definition.protocol == 'udp' and 'bandwidth' not in self._dt_definition.protocol_details:
            if not self._dt_definition.throughput:
                raise DataTransferIllegalArguments("Please provide bandwidth argument at the end of keyword if you use\
                 udp protocol, for example bandwidth=80M")
        dt_config_to_uepc = self._prepare_dt_config_to_uepc()
        self.ue_instance._method_proxy('start_data_transfer', self.name, dt_config_to_uepc)
        self.success_started = True
        timeout = self._get_start_timeout()
        if timeout:
            self._wait_for_data_transfer_start(timeout=timeout)
        self.logger.info('Dt "{}": start with config {}'.format(self.name, dt_config_to_uepc))

    def _get_start_timeout(self):
        timeout = self._dt_definition.protocol_details.get('timeout')
        if timeout:
            return int(timeout)
        return 0

    def stop(self):
        """
        Stops already running data transfer.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        """
        try:
            if self.stopping_gate.is_action_required():
                self.logger.info('Stopping Data Transfer {}'.format(self.name))
                self._download_reports()
                self.ue_instance._method_proxy('close_dt', self.name, force_close=True)
        finally:
            self.is_dt_running = False
            self.ue_instance._method_proxy('add_to_force_stopped', self.name)

    def await_finish(self):
        """
        Waits until this data transfer finish.

        Fires exception if given data transfer (selected by it's name) was not started yet.
        No action if given data transfer is already finished.
        :return: None
        :raises: :py:class:`ute_ue.exceptions.DataTransferCantWaitForeverException`: If this DT has 'forever' duration
        """
        if self.get_definition().is_forever_duration():
            raise DataTransferException("Can not await forever."
                                        "\nPlease set finite duration for {} data transfer".format(self.name))
        try:
            while True:
                finish = self._proxy_is_data_transfer_finish()
                if finish:
                    break
                time.sleep(1)
        finally:
            self._download_reports()
        self.logger.info('Dt "{}": stop'.format(self.name))

    def _download_reports(self, tail=0):
        reports = self.ue_instance._method_proxy('get_dt_reports', self.name, tail)
        self.client_lines_report, self.server_lines_report = reports[0], reports[1]
        if len(reports) > 2:
            cmds = reports[2]
            self.iperf_cmds = cmds
            print("iperf cmds: " + '\n'.join("{} = {}".format(k, v) for k, v in list(cmds.items())))
        self.reports_received = True
        try:
            print('Dt {} iperf client report:\n{}'.format(self.name, '\n'.join(self.client_lines_report)))
            print('Dt {} iperf server report:\n{}'.format(self.name, '\n'.join(self.server_lines_report)))
        except UnicodeEncodeError as e:
            self.logger.debug("UnicodeEncodeError: {} \n {}".format(self.client_lines_report, self.server_lines_report))
            self.logger.error(e, exc_info=True)
            raise e

    def is_running(self):
        """
        Check if data transfer is running

        :return: boolean
        """
        if not self.is_dt_running:
            return False
        finish = self._proxy_is_data_transfer_finish()
        return not finish

    def check_data_transfer(self):
        """Check if data transfer client and server output is progressing"""
        try:
            self.logger.debug('Checking if data transfer is alive...')
            self.ue_instance._method_proxy('check_data_transfer', self.name)
        finally:
            self._download_reports(tail=60)

    def _wait_for_data_transfer_start(self, timeout=180):
        self.logger.debug('Waiting for data transfer start. Timeout: {}'.format(timeout))
        dt_started = self.ue_instance._method_proxy('is_data_transfer_started', self.name)
        if dt_started:
            self.logger.debug('Data transfer should already be running.')
            self.is_dt_running = True
            return
        end_time = time.time() + timeout
        while not dt_started and time.time() < end_time:
            self.logger.debug('Waiting for data transfer start')
            dt_started = self.ue_instance._method_proxy('is_data_transfer_started', self.name)
            if dt_started:
                self.logger.debug('Data transfer should be running now!')
                self.is_dt_running = True
                return
            time.sleep(1)
        raise DataTransferException('Data transfer {} failed to start within {}s timeout on {} UE'.format(self.name,
                                                                                                          timeout,
                                                                                                          self.ue_instance.serial_number))

    def get_average_throughput(self, omit=0, end=0, tput_collection_src="iperf"):
        """
        Method for getting average throughput of data transfer.
        Average throughput is measured from 'dt.start()' to current time or from 'dt.start()' to 'dt.stop()' if data transfer is already finished
        or with currently available iperf intervals that were already transfered.
        :param omit: it is a delay in seconds to start counting the tput ex. '20' - 1st 20 seconds of datatransfer will be omitted.
        :return: value of Average throughput in unit: Kbits/sec
        """
        avg_throughput = self.ue_instance._method_proxy('count_avg_throughput', self.name,
                                                        omit=omit, end=end, tput_collection_src=tput_collection_src)
        self.avg_throughput = self._convert_to_kbits_and_log(avg_throughput)
        return self.avg_throughput

    def _convert_to_kbits_and_log(self, value_in_bits):
        if value_in_bits == -1 or value_in_bits is None:
            self.logger.info("No data to count average throughput.")
            return -1
        avg_throughput_in_kbits = value_in_bits / 1000
        self.logger.info('{} average throughput: {} [kbits/sec]'.format(self.name, avg_throughput_in_kbits))
        return avg_throughput_in_kbits

    def get_datagram_loss(self):
        """
        Getting datagram loss of UDP data transfer
        :return: value of datagram loss in %
        """
        if self.datagram_loss_readed:
            return self.datagram_loss
        if self.is_running():
            raise DataTransferException("Getting datagram loss of non-finished data transfer is not implemented.")
        if self._dt_definition.protocol != 'udp':
            raise DataTransferException('Please use UDP protocol to verify datagram loss.')

        self.datagram_loss = self.ue_instance._method_proxy('get_datagram_loss', self.name)
        self.datagram_loss_readed = True
        if self.datagram_loss is not None:
            print('{} datagram loss equals to {}%'.format(self.name, self.datagram_loss))
            return self.datagram_loss

        raise DataTransferException('None of the datagram received. Unable to count datagram loss.')

    def release_data_transfer(self):
        """Releases resources on remote UE PC."""
        if self.stopping_gate.is_action_required():
            self.ue_instance._method_proxy('release_dt_name', self.name, force_close=True)
        self.logger.debug('Data transfer {} force released. No need to release again'.format(self.name))

    def _proxy_is_data_transfer_finish(self):
        is_data_transfer = self.ue_instance._method_proxy('is_data_transfer_finish', self.name)
        return is_data_transfer

    def get_client_report_rows(self):
        """
        Returns client iperf report received after stop data transfer, or empty list.
        :return: List[IperfServerReportRow]
        """
        return self._report2rows(self.client_lines_report)

    def get_server_report_rows(self):
        """
        Returns server iperf report received after stop data transfer, or empty list.
        :return: List[IperfServerReportRow]
        """
        return self._report2rows(self.server_lines_report)

    def _report2rows(self, report):
        rows = []
        for line in report:
            row = IperfServerReportRow(line)
            if row.correct:
                rows.append(row)
        return rows

    def _prepare_dt_config_to_uepc(self):
        class_to_packer_map = {'AndroidUe': AndroidUeDtConfigPacker, 'AtCmdsUe': AtCmdsUeDtConfigPacker}
        ue_class = self.ue_instance.__class__.__name__
        packer = class_to_packer_map.get(ue_class, AndroidUeDtConfigPacker)
        config_packer = packer(self._dt_definition, self._configuration)
        return config_packer.get_config()

    def get_data_transfer_statistics(self):
        """
        Get data transfer statistics
        :return:
        """
        statistics = self.ue_instance._method_proxy('get_data_transfer_statistics', self.name)
        if not statistics:
            self.logger.info("Unable to count data transfer statistics.")
            return str()
        basic_stats, all_values = statistics.split(';')
        # Values received in bits/s. Converting to kbits/s:
        avg_thr, min_thr, max_thr = [float(value) / 1000 for value in basic_stats.split(',')]
        self.logger.info("{} data transfer statistics:\n"
                         "avg: {} [kbits/s]\n"
                         "min: {} [kbits/s]\n"
                         "max: {} [kbits/s]".format(self.name, avg_thr, min_thr, max_thr))
        self.logger.info("RAW bits/s interval values: \n{}".format(all_values))
        return statistics

    def reset_statistics(self):
        """
        Does nothing here.
        :return:
        """
        pass


class AndroidUeDtConfigPacker(object):
    """AndroidUeDtConfigPacker"""

    def __init__(self, dt_definition, yaml_config):
        """
        Packs data transfer settings from DataTransferDefinition (robot kwargs) and
        yaml config (configuration & data_transfer section) into one dict
        :param dt_definition: DataTransferDefinition class instance
        :param yaml_dt_config: data_transfer section from yaml config
        """
        self.dt_config_to_uepc = {'duration': dt_definition.duration, 'direction': dt_definition.direction, 'protocol': dt_definition.protocol,
                                  'robot_kwargs': dt_definition.protocol_details,
                                  'app_server': self.get_app_server(self._pack_app_servers(yaml_config['data_transfer']),
                                                                    dt_definition.protocol_details)}

        self.set_ip_version_for_app_server()
        self._pack_dt_keys(yaml_config)

        if dt_definition.protocol == 'udp' or (dt_definition.protocol == 'tcp' and not dt_definition.has_default_tput()):
            self._map_legacy_throughput_to_bandwidth(dt_definition)

    def _pack_dt_keys(self, configuration):
        dt_allowed_keys = ['iperf_options', 'iperf_path', 'iperf_interface_name', 'server_close_delay', 'iperf_interval',
                           'iperf_bind_ue_ip', 'tput_collection_src', 'iperf_version', 'iperf_len']
        dt_section = configuration['data_transfer']

        self._apply_allowed_keys(self.dt_config_to_uepc, dt_section, dt_allowed_keys)

    def _apply_allowed_keys(self, dt_config_to_uepc, yaml_config_section, allowed_keys):
        """
        Applies allowed key from selected section into dt dict that goes to UE PC
        :param yaml_config: yaml_config
        :return:
        """
        for key in allowed_keys:
            if key in yaml_config_section:
                dt_config_to_uepc[key] = yaml_config_section[key]
                self._change_legacy_key(key)
                continue
            dt_config_to_uepc[key] = None

    def _pack_app_servers(self, yaml_dt_config):
        if 'app_servers' in yaml_dt_config:
            return yaml_dt_config['app_servers']
        if 'ssh' in yaml_dt_config:
            return self._pack_legacy_ssh(yaml_dt_config)
        raise DtConfigOptionMissingException('Please specify app_servers or ssh section in yaml config')

    def get_app_server(self, app_servers_dict, robot_kwargs):
        """Method's name says everything"""
        if 'app_server' in robot_kwargs:
            app_server = app_servers_dict.get(robot_kwargs['app_server'])
            if not app_server:
                raise AppServerNotAvailableException("Please verify you app server list at configuration yaml:\n"
                                                     "The '{}' app server is missing.\n"
                                                     "App servers configured: {}\n".format(robot_kwargs['app_server'], app_servers_dict.keys()))
            return app_server
        app_servers = app_servers_dict.values()
        if len(app_servers) > 1:
            raise AppServerNotSelectedException("app_server parameter in robot arguments is missing\n Please specify "
                                                "which app server You wish to use.\n App servers configured: {}\n"
                                                .format(app_servers_dict.keys()))
        return six.next(six.itervalues(app_servers_dict))

    def set_ip_version_for_app_server(self):
        """Set ip version for app server based on iperf_interface_ip"""
        app_server = self.dt_config_to_uepc['app_server']
        iperf_interface_ip = app_server.get('iperf_interface_ip')
        if iperf_interface_ip:
            ip_version = get_ip_version(iperf_interface_ip)
            self.dt_config_to_uepc['app_server']['ip_version'] = ip_version
            return
        self.dt_config_to_uepc['app_server']['ip_version'] = 4

    def has_multiple_app_servers_defined_in_config(self, app_servers_section):
        """Method's name says everything"""
        return len(app_servers_section) > 1

    def get_config(self):
        """Methods name says everything"""
        return self.dt_config_to_uepc

    def _pack_legacy_ssh(self, yaml_dt_config):
        """
        Creates a single dummy app server based on legacy ssh section
        to be consistent with new config hierarchy
        """
        app_server = {'ssh': yaml_dt_config['ssh']}
        if 'iperf_interface_ip' in yaml_dt_config:
            app_server['ssh']['iperf_interface_ip'] = yaml_dt_config['iperf_interface_ip']
        return app_server

    def _change_legacy_key(self, old_key):
        backward_compatibility_map = {'iperf_loc': 'iperf_path'}
        if old_key in backward_compatibility_map:
            new_key = backward_compatibility_map[old_key]
            self.dt_config_to_uepc[new_key] = self.dt_config_to_uepc[old_key]
            del self.dt_config_to_uepc[old_key]

    def _map_legacy_throughput_to_bandwidth(self, dt_definition):
        """Maps legacy throughput parameter into bandwidth before inserting into packed UE PC config"""
        if not dt_definition.protocol_details.get('bandwidth', ''):
            dt_definition.protocol_details['bandwidth'] = '{}{}'.format(int(dt_definition.throughput),
                                                                        UNIT_OF_DT_DEFINITION_THROUGHPUT)
        return dt_definition


class AtCmdsUeDtConfigPacker(AndroidUeDtConfigPacker):
    """AtCmdsUeDtConfigPacker"""

    def _pack_dt_keys(self, configuration):
        dt_allowed_keys = ['iperf_options', 'iperf_mode', 'serial_number', 'iperf_path', 'iperf_interface_name',
                           'server_close_delay', 'iperf_interval', 'iperf_bind_ue_ip', 'traffic_type', 'iperf_version',
                           'iperf_len']
        cfg_allowed_keys = ['iperf_loc']
        dt_section = configuration['data_transfer']

        self._apply_allowed_keys(self.dt_config_to_uepc, dt_section, dt_allowed_keys)
        self._apply_allowed_keys(self.dt_config_to_uepc, configuration, cfg_allowed_keys)
